import type { Metadata } from 'next';
import { SITE_NAME, SITE_URL } from './site';

/** Default share image (generated by app/og/route.tsx). */
export const DEFAULT_OG_IMAGE = { url: '/og', width: 1200, height: 630, alt: `${SITE_NAME}: neatly used home items in Nigeria` };

/**
 * Share-preview image from a Cloudinary photo: 1200x630, smart-cropped, JPEG.
 * JPEG (not f_auto) because WhatsApp/Facebook crawlers don't reliably handle WebP/AVIF,
 * and q_auto:eco keeps it well under WhatsApp's ~300 KB preview limit.
 */
export function ogImageFromPhoto(url: string): string {
  if (!url.includes('res.cloudinary.com') || !url.includes('/image/upload/')) return url;
  return url.replace('/image/upload/', '/image/upload/c_fill,g_auto,w_1200,h_630,f_jpg,q_auto:eco/');
}

type PageMetaInput = {
  title: string;
  description: string;
  /** Path for canonical + og:url, e.g. "/items?category=fridges" */
  path: string;
  image?: { url: string; width?: number; height?: number; alt?: string };
  noindex?: boolean;
  /** Use the title as-is (no " | DammyRex Declutter" suffix) */
  absoluteTitle?: boolean;
};

/**
 * Builds consistent page metadata: title, description, canonical, Open Graph and Twitter card.
 * Next.js replaces (doesn't merge) openGraph between layout and page, so every page sets it fully here.
 */
export function pageMetadata({ title, description, path, image, noindex, absoluteTitle }: PageMetaInput): Metadata {
  const img = image ?? DEFAULT_OG_IMAGE;
  const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    robots: noindex ? { index: false, follow: true } : undefined,
    openGraph: {
      type: 'website',
      siteName: SITE_NAME,
      locale: 'en_NG',
      url: path,
      title: fullTitle,
      description,
      images: [{ width: 1200, height: 630, ...img }],
    },
    twitter: {
      card: 'summary_large_image',
      title: fullTitle,
      description,
      images: [img.url],
    },
  };
}

/** Serialise JSON-LD safely inside a <script> tag. */
export function jsonLd(data: unknown): { __html: string } {
  return { __html: JSON.stringify(data).replace(/</g, '\\u003c') };
}

export const absoluteUrl = (path: string) => `${SITE_URL}${path.startsWith('/') ? path : `/${path}`}`;
